import React, { useEffect, useState } from "react";
import io from "socket.io-client";

const backEndUrl = "http://localhost:8000";

const Chat = () => {
    const [user, setUser] = useState("");
    const [room, setRoom] = useState("");
    const [socket, setSocket] = useState(null);
    const [msg, setMsg] = useState("");
    const [messages, setMessages] = useState([]);
    const [typingUser, setTypingUser] = useState("");

    useEffect(() => {
        const searchParams = new URLSearchParams(window.location.search);
        const name = searchParams.get("name")?.trim() || "Anonymous";
        const roomParam = searchParams.get("room")?.trim() || "General";

        setUser(name);
        setRoom(roomParam);

        const newSocket = io(backEndUrl, { transports: ["websocket"], reconnection: true });

        newSocket.on("connect", () => {
            newSocket.emit("joinRoom", { name, room: roomParam });
        });

        newSocket.on("message", (msg) => {
            setMessages((prev) => [...prev, msg]);
            setTypingUser("");
        });

        newSocket.on("typing", (typingName) => {
            if (typingName !== name) {
                setTypingUser(`${typingName} is typing...`);
                setTimeout(() => setTypingUser(""), 2000);
            }
        });

        setSocket(newSocket);

        return () => newSocket.disconnect();
    }, []);

    const sendMessage = (e) => {
        e.preventDefault();
        if (!msg.trim()) return;

        const timestamp = new Date().toLocaleTimeString();
        socket.emit("sendMsg", { text: msg, timestamp }, () => setMsg(""));
    };

    const handleTyping = () => {
        socket.emit("typing", user);
    };

    return (
        <div style={{ maxWidth: "400px", margin: "20px auto", padding: "20px", border: "1px solid #ccc", borderRadius: "8px", fontFamily: "Arial, sans-serif" }}>
            <h2 style={{ textAlign: "center" }}>Chat Room: {room}</h2>
            <div style={{ height: "300px", overflowY: "auto", border: "1px solid #ddd", padding: "10px", marginBottom: "10px" }}>
                {messages.map((message, idx) => (
                    <div key={idx} style={{ padding: "5px 0" }}>
                        <strong>{message.user}:</strong> {message.text} <span style={{ fontSize: "0.8em", color: "gray" }}>({message.timestamp})</span>
                    </div>
                ))}
            </div>
            {typingUser && <p style={{ color: "gray", fontSize: "0.9em" }}>{typingUser}</p>}
            <input
                type="text"
                value={msg}
                onChange={(e) => setMsg(e.target.value)}
                onKeyDown={handleTyping} // Fixed: onKeyPress deprecated
                style={{ width: "100%", padding: "10px", border: "1px solid #ccc", borderRadius: "4px", marginBottom: "10px" }}
            />
            <button onClick={sendMessage} style={{ width: "100%", padding: "10px", background: "blue", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
                Send
            </button>
        </div>
    );
};

export default Chat;
